// Sprint 2.41A — Mid-Size OCR Image Test
// Tries each image variant from smallest to largest
// For each: fill OCR callbacks → Node.next() → check stage → try bridge.next()

Java.perform(function () {
    console.log("[MID] === Mid-Size OCR Image Test ===");

    var TextInputCallback = Java.use("org.forgerock.android.auth.callback.TextInputCallback");
    var ChoiceCallback = Java.use("org.forgerock.android.auth.callback.ChoiceCallback");
    var NodeListener = Java.use("org.forgerock.android.auth.NodeListener");
    var Proxy = Java.use("java.lang.reflect.Proxy");
    var IH = Java.use("java.lang.reflect.InvocationHandler");
    var PromiseCls = Java.use("com.facebook.react.bridge.Promise");
    var FRB = Java.use("com.bangkokbank.blue.ping.FRAuthBridge");

    // Image variants (smallest first)
    var variants = [{"name": "240x160_q80", "w": 240, "h": 160, "q": 80, "jpeg": 12969, "b64": 17292, "data": ""}, {"name": "320x213_q75", "w": 320, "h": 213, "q": 75, "jpeg": 18782, "b64": 25044, "data": ""}, {"name": "360x240_q70", "w": 360, "h": 240, "q": 70, "jpeg": 21169, "b64": 28228, "data": ""}, {"name": "480x320_q65", "w": 480, "h": 320, "q": 65, "jpeg": 30457, "b64": 40612, "data": ""}];

    var currentVariant = 0;
    var responseStage = null;
    var responseAuthId = null;
    var responseAuthIdLen = 0;
    var bridgeResult = null;
    var uiTransitioned = false;
    var attemptLog = [];

    // Mock promise (reusable)
    var mockPromise = Proxy.newProxyInstance(
        PromiseCls.class.getClassLoader(),
        Java.array("java.lang.Class", [PromiseCls.class]),
        Java.registerClass({
            name: "com.frida.MP" + Date.now(),
            implements: [IH],
            methods: { invoke: function(p, m, a) {
                var mn = m.getName();
                if (mn === "resolve") { bridgeResult = "RESOLVED"; console.log("[PROMISE] *** RESOLVED! ***"); }
                if (mn === "reject" && a) {
                    bridgeResult = "REJECTED";
                    console.log("[PROMISE] REJECTED: " + (a[1] ? a[1].toString().substring(0, 100) : "?"));
                }
                return null;
            }}
        }).$new()
    );

    // Hook ASC2 to capture server response
    var ASC2 = Java.use("org.forgerock.android.auth.AuthServiceClient$2");
    ASC2.onResponse.implementation = function (call, response) {
        try {
            var body = response.peekBody(2097152).string();
            if (body.indexOf('"stage"') >= 0) {
                var stageMatch = body.match(/"stage"\s*:\s*"([^"]+)"/);
                var authMatch = body.match(/"authId"\s*:\s*"([^"]+)"/);
                responseStage = stageMatch ? stageMatch[1] : "?";
                responseAuthIdLen = authMatch ? authMatch[1].length : 0;
                responseAuthId = authMatch ? authMatch[1] : null;
                console.log("[HOOK] Server response: stage=" + responseStage + " authId=" + responseAuthIdLen);
            }
        } catch (e) {}
        return this.onResponse(call, response);
    };

    // Polling logic
    var pollCount = 0;
    var waitingForResponse = false;
    var waitingForBridge = false;

    var pollInterval = setInterval(function () {
        pollCount++;
        if (uiTransitioned || currentVariant >= variants.length) {
            if (pollCount > 72) clearInterval(pollInterval);
            return;
        }

        Java.perform(function () {
            // State machine
            if (!waitingForResponse && !waitingForBridge) {
                // Phase 1: Find OCR Node, fill callbacks, submit
                Java.choose("org.forgerock.android.auth.Node", {
                    onMatch: function (node) {
                        if (waitingForResponse || waitingForBridge) return;
                        try {
                            if (node.getStage() !== "OCR") return;

                            var v = variants[currentVariant];
                            console.log("\n[MID] *** ATTEMPT " + (currentVariant + 1) + ": " + v.name + " (B64=" + v.b64 + " chars) ***");

                            // Fill callbacks
                            var cbs = node.getCallbacks();
                            Java.cast(cbs.get(0), ChoiceCallback).setSelectedIndex(0);
                            Java.cast(cbs.get(1), TextInputCallback).setValue(v.data);
                            console.log("[MID] Callbacks filled with " + v.name);

                            // Create proxy listener
                            var ctx = Java.use("android.app.ActivityThread").currentApplication().getApplicationContext();
                            var listener = Proxy.newProxyInstance(
                                NodeListener.class.getClassLoader(),
                                Java.array("java.lang.Class", [NodeListener.class]),
                                Java.registerClass({
                                    name: "com.frida.MNL" + Date.now() + currentVariant,
                                    implements: [IH],
                                    methods: { invoke: function(p, m, a) { return null; }}
                                }).$new()
                            );

                            // Reset response state
                            responseStage = null;
                            responseAuthId = null;
                            responseAuthIdLen = 0;
                            bridgeResult = null;

                            // Submit
                            console.log("[MID] Calling Node.next()...");
                            node.next(ctx, listener);
                            waitingForResponse = true;
                            console.log("[MID] Waiting for server response...");

                        } catch (e) { console.log("[MID] Submit error: " + e); }
                    },
                    onComplete: function () {}
                });
            }

            // Phase 2: Response received — analyze
            if (waitingForResponse && responseStage) {
                waitingForResponse = false;
                var v = variants[currentVariant];
                console.log("[MID] Response: stage=" + responseStage + " authId=" + responseAuthIdLen);

                if (responseStage === "NTB_LC") {
                    console.log("[MID] *** OCR ACCEPTED " + v.name + "! ***");
                    console.log("[MID] Attempting bridge.next()...");

                    // Phase 3: Try bridge.next()
                    waitingForBridge = true;
                    bridgeResult = null;

                    var authIdJson = JSON.stringify({authId: responseAuthId});
                    console.log("[MID] authIdJson: " + authIdJson.length + " chars");

                    Java.choose("com.bangkokbank.blue.ping.FRAuthBridge", {
                        onMatch: function (bridge) {
                            try {
                                bridge.next(authIdJson, mockPromise);
                                console.log("[MID] bridge.next() sent");
                            } catch (e) {
                                bridgeResult = "ERROR:" + e;
                                console.log("[MID] bridge.next() error: " + e);
                            }
                        },
                        onComplete: function () {}
                    });

                    // Wait 8 seconds for bridge result
                    setTimeout(function () {
                        console.log("[MID] Bridge result: " + bridgeResult);

                        // Log attempt
                        attemptLog.push({
                            variant: v.name,
                            b64len: v.b64,
                            serverStage: responseStage,
                            authIdLen: responseAuthIdLen,
                            bridgeResult: bridgeResult
                        });
                        console.log("[MID] === ATTEMPT " + (currentVariant + 1) + " RESULT: " + bridgeResult + " ===");

                        if (bridgeResult === "RESOLVED") {
                            console.log("[MID] *** BRIDGE RESOLVED — checking UI... ***");
                            uiTransitioned = true;
                        } else {
                            console.log("[MID] Bridge failed — flow stuck at NTB_LC");
                            console.log("[MID] Cannot try more variants (authId consumed)");
                            currentVariant = variants.length; // Stop
                        }
                        waitingForBridge = false;
                    }, 8000);

                } else if (responseStage === "OCR") {
                    console.log("[MID] OCR rejected " + v.name + " — trying next variant");
                    attemptLog.push({
                        variant: v.name,
                        b64len: v.b64,
                        serverStage: "OCR (rejected)",
                        authIdLen: responseAuthIdLen,
                        bridgeResult: "N/A"
                    });
                    currentVariant++;
                } else {
                    console.log("[MID] Unexpected stage: " + responseStage);
                    currentVariant++;
                }
            }
        });

        if (pollCount > 72) { clearInterval(pollInterval); }
    }, 3000);

    console.log("[MID] Polling started. Variants to try: " + variants.length);
});
